/**
 * Language resolution driven by CodeMirror's own mode metadata.
 *
 * mode-info.json is generated by scripts/build-modes.mjs from the vendored
 * CodeMirror package, so this covers every language that package knows about
 * instead of a hand-maintained list that silently falls behind. A file whose
 * extension is unknown still opens and still edits; only highlighting is
 * absent, and the UI says so.
 */

import fs from "node:fs";

const TABLE_URL = new URL("../../../renderer/vendor/codemirror/mode-info.json", import.meta.url);

export const PLAIN_TEXT = { label: "Plain text", mode: null, modeFile: null, id: "text" };

function loadTable() {
  try {
    const raw = fs.readFileSync(TABLE_URL, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export const LANGUAGE_TABLE = loadTable();

const byExtension = new Map();
const filenameRules = [];

for (const entry of LANGUAGE_TABLE) {
  const language = {
    label: entry.name,
    mode: entry.mimes?.[0] ?? null,
    modeFile: entry.mode ?? null,
    id: entry.mode ?? entry.name.toLowerCase(),
    allMimes: entry.mimes ?? [],
  };
  for (const ext of entry.ext ?? []) {
    const key = String(ext).toLowerCase();
    if (!byExtension.has(key)) byExtension.set(key, language);
  }
  if (entry.file?.source) {
    try {
      filenameRules.push({ pattern: new RegExp(entry.file.source, entry.file.flags ?? ""), language });
    } catch {
      /* a malformed rule in metadata should not break every lookup */
    }
  }
}

/** Language descriptor for a relative path; never throws. */
export function languageFor(relativePath) {
  const name = String(relativePath ?? "").split("/").pop() ?? "";
  if (!name) return { ...PLAIN_TEXT };

  for (const rule of filenameRules) {
    if (rule.pattern.test(name)) return { ...rule.language };
  }

  const lower = name.toLowerCase();
  const dot = lower.lastIndexOf(".");
  const ext = dot > 0 ? lower.slice(dot + 1) : lower;
  const found = byExtension.get(ext);
  if (found) return { ...found };

  return { ...PLAIN_TEXT, id: ext || "text" };
}

/** Number of distinct languages the table offers, for UI copy. */
export function languageCount() {
  return new Set(LANGUAGE_TABLE.map((entry) => entry.name)).size;
}

/** Every extension the table resolves, used by tests and the status line. */
export function extensions() {
  return [...byExtension.keys()].sort();
}
